// Package userpg is the Postgres adapter for the user module.
//
// It implements user.Repository on top of sqlc-generated code (the
// sqlc_*.go and queries.sql.go files, regenerated by `make generate`).
// Generated types stay inside this package; everything returned is a
// user.User, and driver errors are translated into user module errors.
package userpg

import (
	"context"
	"time"

	"github.com/google/uuid"

	"github.com/islamghany/goplate/internal/errs"
	"github.com/islamghany/goplate/internal/identity"
	"github.com/islamghany/goplate/internal/page"
	"github.com/islamghany/goplate/internal/platform/postgres"
	"github.com/islamghany/goplate/internal/user"
)

// Repository implements user.Repository.
type Repository struct {
	txm *postgres.TxManager
}

// NewRepository returns a Repository. It takes the TxManager, never the
// pool, so every query automatically joins the caller's transaction.
func NewRepository(txm *postgres.TxManager) *Repository {
	return &Repository{txm: txm}
}

var _ user.Repository = (*Repository)(nil)

func (r *Repository) q(ctx context.Context) *Queries { return New(r.txm.DB(ctx)) }

func (r *Repository) Create(ctx context.Context, u user.User) (user.User, error) {
	row, err := r.q(ctx).InsertUser(ctx, InsertUserParams{
		ID:           u.ID,
		Email:        u.Email,
		Name:         u.Name,
		PasswordHash: u.PasswordHash,
		Role:         string(u.Role),
		CreatedAt:    u.CreatedAt,
	})
	if _, ok := postgres.UniqueViolation(err); ok {
		return user.User{}, user.ErrEmailTaken
	}
	if err != nil {
		return user.User{}, errs.Wrap(errs.Internal, "", err)
	}
	return toDomain(row), nil
}

func (r *Repository) ByID(ctx context.Context, id uuid.UUID) (user.User, error) {
	row, err := r.q(ctx).GetUserByID(ctx, id)
	return one(row, err)
}

func (r *Repository) ByEmail(ctx context.Context, email string) (user.User, error) {
	row, err := r.q(ctx).GetUserByEmail(ctx, email)
	return one(row, err)
}

func (r *Repository) UpdateName(ctx context.Context, id uuid.UUID, name string, at time.Time) (user.User, error) {
	row, err := r.q(ctx).UpdateUserName(ctx, UpdateUserNameParams{ID: id, Name: name, UpdatedAt: at})
	return one(row, err)
}

func (r *Repository) List(ctx context.Context, req page.Request) ([]user.User, error) {
	params := ListUsersParams{RowLimit: int32(req.Limit + 1)} //nolint:gosec // Limit <= page.MaxLimit
	if req.After != nil {
		params.AfterCreatedAt, params.AfterID = &req.After.CreatedAt, &req.After.ID
	}
	rows, err := r.q(ctx).ListUsers(ctx, params)
	if err != nil {
		return nil, errs.Wrap(errs.Internal, "", err)
	}
	out := make([]user.User, len(rows))
	for i, row := range rows {
		out[i] = toDomain(row)
	}
	return out, nil
}

func one(row User, err error) (user.User, error) {
	switch {
	case postgres.IsNoRows(err):
		return user.User{}, user.ErrNotFound
	case err != nil:
		return user.User{}, errs.Wrap(errs.Internal, "", err)
	}
	return toDomain(row), nil
}

func toDomain(row User) user.User {
	return user.User{
		ID:           row.ID,
		Email:        row.Email,
		Name:         row.Name,
		PasswordHash: row.PasswordHash,
		Role:         identity.Role(row.Role),
		CreatedAt:    row.CreatedAt,
		UpdatedAt:    row.UpdatedAt,
	}
}
